// The TOP-LEVEL twin. Nothing resolves to it: vt2-throw-lib's own require
// is satisfied by its private nested copy, and the application never names
// vt2-vuln-lib at all. It is here so that any resolution keyed on package
// NAME AND VERSION rather than on install path lands on the wrong instance
// and says so.
function dangerousOp(input) {
  return reachedSink(input);
}

function reachedSink(input) {
  return "reached-sink:" + input;
}

exports.dangerousOp = dangerousOp;
